Tests below assume the class lives in `late_fee_calculator.py`. Every branch is exercised: `end <= start` (true/false), the weekday check (weekday and weekend days), `balance_cents <= 0` (true/false), and `billable_days <= 0` (true/false). Assertions also cover min fee, the 25% cap, half-up rounding, weekend exclusion, and the quirk that the minimum fee is applied after the cap (so a 100-cent balance still yields a 500-cent fee).

```python
# test_late_fee_calculator.py
from datetime import date

import pytest

from late_fee_calculator import LateFeeCalculator


DUE = date(2024, 1, 1)  # Monday


@pytest.fixture
def calc_on():
    def _make(today):
        return LateFeeCalculator(today=today)
    return _make


class TestInit:
    def test_defaults_to_today_when_not_given(self):
        assert LateFeeCalculator()._today == date.today()

    def test_uses_injected_today(self):
        assert LateFeeCalculator(today=DUE)._today == DUE


class TestWeekdayDaysBetween:
    def test_end_before_start_returns_zero(self):
        calc = LateFeeCalculator(today=DUE)
        assert calc._weekday_days_between(date(2024, 1, 10), DUE) == 0

    def test_end_equal_start_returns_zero(self):
        calc = LateFeeCalculator(today=DUE)
        assert calc._weekday_days_between(DUE, DUE) == 0

    def test_weekend_only_range_returns_zero(self):
        calc = LateFeeCalculator(today=DUE)
        # Sat 2024-01-06 -> Mon 2024-01-08 (end exclusive): Sat, Sun only
        assert calc._weekday_days_between(date(2024, 1, 6), date(2024, 1, 8)) == 0

    def test_range_spanning_weekend_skips_weekend(self):
        calc = LateFeeCalculator(today=DUE)
        # Fri 2024-01-05 -> Tue 2024-01-09 (end exclusive): Fri, Sat, Sun, Mon -> 2
        assert calc._weekday_days_between(date(2024, 1, 5), date(2024, 1, 9)) == 2

    def test_two_full_weeks(self):
        calc = LateFeeCalculator(today=DUE)
        assert calc._weekday_days_between(DUE, date(2024, 1, 15)) == 10


class TestComputeFeeCents:
    @pytest.mark.parametrize("balance", [0, -1, -50000])
    def test_non_positive_balance_returns_zero(self, calc_on, balance):
        calc = calc_on(date(2030, 1, 1))
        assert calc.compute_fee_cents(balance, DUE) == 0

    def test_today_before_due_date_returns_zero(self, calc_on):
        assert calc_on(date(2023, 12, 1)).compute_fee_cents(100000, DUE) == 0

    def test_today_equal_due_date_returns_zero(self, calc_on):
        assert calc_on(DUE).compute_fee_cents(100000, DUE) == 0

    def test_within_grace_period_returns_zero(self, calc_on):
        # Exactly 10 weekdays past due (Mon 2024-01-15): billable_days == 0
        assert calc_on(date(2024, 1, 15)).compute_fee_cents(100000, DUE) == 0

    def test_one_day_past_grace_applies_minimum_fee(self, calc_on):
        # 11 weekdays -> 1 billable day; raw = 100000 * 0.0005 = 50 cents -> min fee wins
        assert calc_on(date(2024, 1, 16)).compute_fee_cents(100000, DUE) == 500

    def test_prorated_fee_above_minimum_below_cap(self, calc_on):
        # 30 weekdays -> 20 billable days; 100000 * 0.0005 * 20 = 1000
        assert calc_on(date(2024, 2, 12)).compute_fee_cents(100000, DUE) == 1000

    def test_rounds_half_up(self, calc_on):
        # 100050 * 0.0005 * 20 = 1000.5 -> 1001
        assert calc_on(date(2024, 2, 12)).compute_fee_cents(100050, DUE) == 1001

    def test_rounds_down_below_half(self, calc_on):
        # 100010 * 0.0005 * 20 = 1000.1 -> 1000
        assert calc_on(date(2024, 2, 12)).compute_fee_cents(100010, DUE) == 1000

    def test_fee_capped_at_25_percent_of_balance(self, calc_on):
        # ~784 weekdays -> raw fee far exceeds 25% of 10000
        assert calc_on(date(2027, 1, 1)).compute_fee_cents(10000, DUE) == 2500

    def test_minimum_fee_overrides_cap_for_tiny_balances(self, calc_on):
        # Cap is 25 cents, but min fee (500) is applied after the cap.
        assert calc_on(date(2027, 1, 1)).compute_fee_cents(100, DUE) == 500

    def test_weekends_not_counted_toward_days_late(self, calc_on):
        # Sat 2024-01-13 and Mon 2024-01-15 both give 10 weekdays -> still in grace
        assert calc_on(date(2024, 1, 13)).compute_fee_cents(100000, DUE) == 0
        assert calc_on(date(2024, 1, 14)).compute_fee_cents(100000, DUE) == 0
        assert calc_on(date(2024, 1, 15)).compute_fee_cents(100000, DUE) == 0
